    $('#source-input').addEventListener('input',()=>{this.renderHighlight();clearTimeout(this.sourceTimer);this.sourceTimer=setTimeout(()=>this.commitSource(),350);this.sourcePosition();});
    $('#source-input').addEventListener('scroll',()=>{const s=$('#source-input');$('#syntax-highlight').scrollTop=s.scrollTop;$('#syntax-highlight').scrollLeft=s.scrollLeft;$('#line-numbers').scrollTop=s.scrollTop;});
    $('#source-input').addEventListener('click',()=>this.sourcePosition());$('#source-input').addEventListener('keyup',()=>this.sourcePosition());
    $('#source-input').addEventListener('keydown',e=>{if(e.key==='Tab'){e.preventDefault();const t=e.target,start=t.selectionStart,end=t.selectionEnd;t.setRangeText('  ',start,end,'end');t.dispatchEvent(new Event('input'));}});
    $('#find-input').addEventListener('input',()=>this.updateFindCount());$('#find-input').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();this.findNext();}if(e.key==='Escape')this.run('close-find');});
    $('#import-input').addEventListener('change',e=>{this.importFiles([...e.target.files]);e.target.value='';});
    $('#image-import-input').addEventListener('change',async e=>{const files=[...e.target.files];if(!files.length)return;try{const f=await this.importSingle(files[0],'assets/');if($('#modal').open&&$('#modal [name=src]'))$('#modal [name=src]').value=relativePath(this.model.active.path,f.path);else{await this.ensureDesign();this.editor.insertHTML(`<img src="${escapeHTML(relativePath(this.model.active.path,f.path))}" alt="${escapeHTML(files[0].name.replace(/\.[^.]+$/,''))}" style="max-width:100%;height:auto">`,'Insert image');}}catch(error){this.toast(error.message,true);}e.target.value='';});
    document.addEventListener('keydown',e=>this.keydown(e));
    window.addEventListener('message',e=>{if(e.source!==$('#preview-frame').contentWindow||e.data?.channel!==this.channelId)return;if(e.data.type==='pageforge:navigate'&&typeof e.data.path==='string'&&this.model.get(e.data.path)&&isHTML(e.data.path))this.openFile(e.data.path);else if(e.data.type==='pageforge:preview-error')this.toast('Preview script: '+String(e.data.message).slice(0,250),true);});
