  async ensureDesign(){if(!isHTML(this.model.active.path))throw new Error('Open an HTML page to use the visual editor.');if(this.view!=='page'||this.mode==='code'||this.mode==='preview')await this.setMode('design');if(!this.editor.doc||this.editor.path!==this.model.active.path)await this.editor.load(this.model.active.path);}
  async setMode(mode){if(!['design','split','code','preview'].includes(mode))return;this.flush();if(!isHTML(this.model.active.path)&&mode!=='code'){this.toast('Visual views are available for HTML pages. Open an HTML file first.',true);return;}const previous=this.mode;this.mode=mode;this.view='page';this.renderViewState();this.renderModeState();this.renderTabs();if(mode==='preview')this.renderPreview();else if(mode==='design'||mode==='split'){if(previous==='code'||previous==='preview'||this.editor.path!==this.model.active.path)await this.editor.load(this.model.active.path);}if(mode==='code'||mode==='split')this.renderSource(true);this.renderInspector();this.layout();}
  renderModeState(){$('#editor-workspace').dataset.mode=this.mode;$$('.mode-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.mode===this.mode);b.setAttribute('aria-selected',String(b.dataset.mode===this.mode));});const preview=this.mode==='preview';$('#design-frame').hidden=preview;$('#preview-frame').hidden=!preview;$('#preview-notice').hidden=!preview;$('#format-toolbar').classList.toggle('inactive',this.mode==='code'||preview);$('#document-hint').textContent=preview?'Sandboxed preview · click links to navigate':this.mode==='code'?'Source is the document · changes save automatically':'Click to edit · Esc to select parent';if(preview||this.mode==='code'){this.renderer.begin();this.renderer.draw();$('#selection-label').hidden=true;$('#resize-handles').innerHTML='';}}
  setView(view){this.flush();this.view=view;this.renderViewState();this.renderTabs();if(view!=='page')this.renderSiteView();else this.layout();}
  renderViewState(){$$('.view-button').forEach(b=>b.classList.toggle('active',b.dataset.view===this.view));$('#site-view').hidden=this.view==='page';this.renderModeState();}
